def _make_lookuper(silent):
    def decorator(func):
        memo = {}
        has_args, has_kwargs = has_arg_types(func)

        def lookup(table, key):
            try:
                return table[key]
            except KeyError:
                if silent:
                    return None
                raise LookupError(key)

        if has_args or has_kwargs:
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (args, tuple(sorted(kwargs.items())))
                if key not in memo:
                    memo[key] = dict(func(*args, **kwargs))
                table = memo[key]
                return lambda k: lookup(table, k)
            return wrapper
        else:
            table = dict(func())
            return lambda key: lookup(table, key)

    return decorator
